export const tracks=[{id:'nacional',name:'Hino Nacional · instrumental',src:'assets/music/hino-nacional-verified.mp3'},{id:'bandeira',name:'Hino à Bandeira · instrumental',src:'assets/music/hino-bandeira-verified.mp3'}];
class Soundscape{
 constructor(){this.enabled=true;this.musicOn=true;this.fxOn=true;this.musicVolume=.10;this.fxVolume=.5;this.tempo=1.25;this.track=0;this.running=false;this.unlocked=false;this.lastStep=0;try{const saved=JSON.parse(localStorage.getItem('brasa-audio')||'{}');Object.assign(this,saved);if(!saved.mixRevision){if(this.musicVolume===.15)this.musicVolume=.10;if(this.tempo===1.18)this.tempo=1.25}}catch{}this.audio=new Audio();this.audio.preload='none';this.audio.loop=true;this.audio.preservesPitch=true;this.audio.src=tracks[this.track]?.src||tracks[0].src;this.audio.addEventListener('error',()=>{this.error=true;window.dispatchEvent(new Event('brasa-audio-error'))});this.apply()}
 save(){try{localStorage.setItem('brasa-audio',JSON.stringify({mixRevision:1,enabled:this.enabled,musicOn:this.musicOn,fxOn:this.fxOn,musicVolume:this.musicVolume,fxVolume:this.fxVolume,tempo:this.tempo,track:this.track}))}catch{}}
 apply(){this.audio.volume=this.musicVolume;this.audio.playbackRate=this.tempo;this.audio.preservesPitch=true;if(this.enabled&&this.musicOn&&this.running&&this.unlocked)this.audio.play().catch(()=>{});else this.audio.pause();this.save();window.dispatchEvent(new Event('brasa-audio-change'))}
 unlock(forGame=false){this.unlocked=true;if(forGame)this.running=true;try{this.context??=new AudioContext();this.context.resume();if(!this.master){this.master=this.context.createGain();this.master.gain.value=.6;const limiter=this.context.createDynamicsCompressor();limiter.threshold.value=-12;limiter.ratio.value=8;this.master.connect(limiter);limiter.connect(this.context.destination)}}catch{}this.apply()}
 setRunning(value){if(this.running!==value){this.running=value;this.apply()}}
 select(index){this.track=index;this.audio.src=tracks[index].src;this.error=false;this.apply()}
 tone(freq,duration,gain=.1,type='sine',end=40){if(!this.context||!this.master)return;const c=this.context,t=c.currentTime,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),t+duration);g.gain.setValueAtTime(gain*this.fxVolume,t);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(this.master);o.start();o.stop(t+duration)}
 noise(duration,frequency,gain=.1,q=.8){if(!this.context||!this.master)return;const c=this.context,n=Math.ceil(c.sampleRate*duration),buffer=c.createBuffer(1,n,c.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,1.7);const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=buffer;f.type='bandpass';f.frequency.value=frequency;f.Q.value=q;g.gain.value=gain*this.fxVolume;s.connect(f);f.connect(g);g.connect(this.master);s.start()}
 fx(kind,force=1){if(!this.enabled||!this.fxOn||!this.unlocked)return;force=Math.max(.25,Math.min(1.5,force));if(kind==='punch'){this.noise(.12,1400,.19*force);this.tone(135,.13,.18*force,'triangle',45)}else if(kind==='kick'){this.noise(.18,650,.24*force);this.tone(100,.22,.25*force,'sine',29)}else if(kind==='hit'){this.noise(.15,1150,.25*force);this.tone(105,.17,.24*force,'sine',32)}else if(kind==='block'){this.noise(.07,2400,.12);this.tone(620,.08,.06,'triangle',250)}else if(kind==='whoosh'){this.noise(.13,2100,.08)}else if(kind==='special'){this.noise(.3,1800,.12);this.tone(170,.3,.12,'sawtooth',580)}else if(kind==='super'){this.noise(.65,700,.24);this.tone(90,.6,.2,'sawtooth',25)}else if(kind==='land'){this.noise(.1,220,.15*force);this.tone(68,.13,.1*force,'sine',30)}else if(kind==='step'){const t=this.context.currentTime;if(t-this.lastStep<.12)return;this.lastStep=t;this.noise(.055,300,.08);this.tone(70,.05,.035,'triangle',35)}else if(kind==='jump'){this.noise(.1,1500,.07)}else if(kind==='break'){this.noise(.3,1300,.2);this.tone(120,.2,.1,'triangle',30)}else if(kind==='pickup'){this.tone(580,.15,.08,'sine',1000)}else if(kind==='fatal'){this.noise(.9,450,.28);this.tone(75,.85,.2,'sawtooth',22)}else this.tone(480,.06,.05,'triangle',300)}
}
export const soundscape=new Soundscape();

window.addEventListener('blur',()=>soundscape.setRunning(false));document.addEventListener('visibilitychange',()=>{if(document.hidden)soundscape.setRunning(false)});
